<script setup lang="ts">
import {computed,onMounted,ref} from 'vue';import {useRoute} from 'vue-router';import {api} from '@/api/gallery';const route=useRoute(),data=ref<any>(),error=ref('');const summary=computed(()=>data.value?.summary||{});onMounted(async()=>{try{data.value=await api(`/space/analyze${route.query.spaceId?`?spaceId=${route.query.spaceId}`:''}`,undefined,'GET')}catch(e){error.value=(e as Error).message}})
</script><template><div class="page-heading"><span class="eyebrow">INSIGHTS</span><h1>图库，让工作更清晰。</h1><p class="muted">用直观数据了解空间的内容和使用情况。</p></div><a-alert v-if="error" type="error" :message="error"/><a-spin :spinning="!data&&!error"><div v-if="data" class="stat-grid"><article class="stat-card"><span>图片总数</span><strong>{{summary.pictureCount}}</strong></article><article class="stat-card"><span>存储容量</span><strong>{{(Number(summary.totalSize)/1024/1024).toFixed(1)}} MB</strong></article><article class="stat-card"><span>浏览总量</span><strong>{{summary.views}}</strong></article><article class="stat-card"><span>下载总量</span><strong>{{summary.downloads}}</strong></article><section class="panel"><h2>分类分布</h2><a-list :data-source="data.categories"><template #renderItem="{item}"><a-list-item>{{item.label||'未分类'}}<a-tag>{{item.count}} 张</a-tag><span>{{(Number(item.size)/1024/1024).toFixed(1)}} MB</span></a-list-item></template></a-list></section><section class="panel"><h2>文件格式</h2><a-list :data-source="data.formats"><template #renderItem="{item}"><a-list-item>{{item.label?.toUpperCase()}}<a-tag>{{item.count}} 张</a-tag></a-list-item></template></a-list></section><section class="panel"><h2>最近 30 天的上传</h2><div class="bars"><div v-for="d in [...data.daily].reverse()" :key="d.label" :title="`${d.label}: ${d.count} 张`" :style="{height:`${Math.max(5,Math.min(100,d.count*12))}%`}"></div></div><small v-if="data.daily[0]">{{data.daily[data.daily.length-1]?.label}} — {{data.daily[0].label}}</small></section></div></a-spin></template>
